/* MOONLINE — the descent. Served from moonline.codifiedresonance.com/descent/ and loaded by the
   embed on codifiedresonance.com/last-platform/moonline. Built from the descent generators. */
(function(){
  var mount = document.getElementById("moonline-descent");
  if(!mount) return;
  mount.innerHTML = "<section class=\"ml-descent\" aria-label=\"MOONLINE \u2014 the line\">\n  <div class=\"ml-cosmos\" data-ml-cosmos aria-hidden=\"true\"></div>\n  <div class=\"ml-limb\" aria-hidden=\"true\"></div>\n\n  <header class=\"ml-head\">\n    <p class=\"ml-kicker\"><a class=\"ml-up\" href=\"/last-platform/node\">&lsaquo; The Last Platform</a><span class=\"ml-kick-tail\"> &middot; the line</span></p>\n    <h1 class=\"ml-title\" aria-label=\"MOONLINE\">\n      <span class=\"ml-title-word\">MOONLINE</span>\n    </h1>\n    <p class=\"ml-standfirst ml-long\">\n      Five crossings. One intensement \u2014 a re-feel of the forces at play in the universe:\n      impact, light, heat, current, gravity \u2014 and the science is the antagonist.\n      The game works out the current week for itself and builds every world from it \u2014\n      no server, nothing published, nothing to maintain. Everyone who opens MOONLINE\n      this week is crossing the identical universe, automatically, and every seven\n      Earth days it becomes a new one. Cross it well and you may leave your line:\n      held on this device, yours to keep or to hand to another witness.\n    </p>\n\n    <p class=\"ml-standfirst ml-short\">\n      Five crossings. A re-feel of the forces at play in the universe, and the science is the antagonist.\n      This week everyone crosses the identical universe. Cross it well and you may leave your line.\n    </p>\n\n    <p class=\"ml-cycle\" data-ml-cycle aria-live=\"polite\"></p>\n\n    <div class=\"ml-progress\" data-ml-progress>\n      <span class=\"ml-progress-track\"><span class=\"ml-progress-fill\" data-ml-fill></span></span>\n      <span class=\"ml-progress-read\" data-ml-read>0 of 5 crossed</span>\n    </div>\n    <p class=\"ml-edition ml-emerge\"><span class=\"ml-gold\">edition i</span><span class=\"ml-edition-sep\">&middot;</span><span class=\"ml-gold\">the proving ground</span></p>\n  </header>\n\n  <ol class=\"ml-tracks\" data-ml-tracks data-ml-ed=\"1\">\n\n    <li class=\"ml-track\" data-ml-index=\"1\" data-ml-key=\"crossing\"\n        data-track=\"crossing/\">\n      <span class=\"ml-track-rule\"></span>\n      <div class=\"ml-track-body\">\n        <p class=\"ml-track-num\">01</p>\n        <h2 class=\"ml-track-name\">The Crossing</h2>\n        <p class=\"ml-track-place\">Earth station \u2192 the Moon</p>\n        <p class=\"ml-track-force\"><span class=\"ml-force-label\">force</span> impact \u00b7 the long emptiness</p>\n        <p class=\"ml-track-line\">The long one. Endurance across nothing, punctuated by rock.</p>\n      </div>\n      <div class=\"ml-track-state\" data-ml-state>\n        <span class=\"ml-enter\">Enter <span class=\"ml-arrow\">&rsaquo;</span></span>\n      </div>\n    </li>\n\n    <li class=\"ml-track\" data-ml-index=\"2\" data-ml-key=\"ringfall\"\n        data-track=\"ringfall/\">\n      <span class=\"ml-track-rule\"></span>\n      <div class=\"ml-track-body\">\n        <p class=\"ml-track-num\">02</p>\n        <h2 class=\"ml-track-name\">Ringfall</h2>\n        <p class=\"ml-track-place\">Saturn's rings</p>\n        <p class=\"ml-track-force\"><span class=\"ml-force-label\">force</span> information \u00b7 can you see in time</p>\n        <p class=\"ml-track-line\">A dive through a sheet ten metres thick and a quarter-million kilometres wide. Shear, shadow, spokes. The ice keeps its own orbit.</p>\n      </div>\n      <div class=\"ml-track-state\" data-ml-state></div>\n    </li>\n\n    <li class=\"ml-track\" data-ml-index=\"3\" data-ml-key=\"ironlight\"\n        data-track=\"ironlight/\">\n      <span class=\"ml-track-rule\"></span>\n      <div class=\"ml-track-body\">\n        <p class=\"ml-track-num\">03</p>\n        <h2 class=\"ml-track-name\">Ironlight</h2>\n        <p class=\"ml-track-place\">KELT-9b \u00b7 the hottest known orbit</p>\n        <p class=\"ml-track-force\"><span class=\"ml-force-label\">force</span> heat \u00b7 you cannot dodge it, only budget it</p>\n        <p class=\"ml-track-line\">Around a star so fierce iron hangs vaporised in the sky. Heat is time; speed is cooling; the deep breath of the tail is mercy.</p>\n      </div>\n      <div class=\"ml-track-state\" data-ml-state></div>\n    </li>\n\n    <li class=\"ml-track\" data-ml-index=\"4\" data-ml-key=\"behemoth\"\n        data-track=\"behemoth/\">\n      <span class=\"ml-track-rule\"></span>\n      <div class=\"ml-track-body\">\n        <p class=\"ml-track-num\">04</p>\n        <h2 class=\"ml-track-name\">The Behemoth</h2>\n        <p class=\"ml-track-place\">GJ 436b \u00b7 an exhaled sky</p>\n        <p class=\"ml-track-force\"><span class=\"ml-force-label\">force</span> current \u00b7 the medium itself moves you</p>\n        <p class=\"ml-track-line\">A comet-tail of hydrogen larger than its star, surviving only because the star is too gentle to blow it away. Ride the breath out.</p>\n      </div>\n      <div class=\"ml-track-state\" data-ml-state></div>\n    </li>\n\n    <li class=\"ml-track\" data-ml-index=\"5\" data-ml-key=\"well\"\n        data-track=\"well/\">\n      <span class=\"ml-track-rule\"></span>\n      <div class=\"ml-track-body\">\n        <p class=\"ml-track-num\">05</p>\n        <h2 class=\"ml-track-name\">The Well</h2>\n        <p class=\"ml-track-place\">A spinning supermassive black hole</p>\n        <p class=\"ml-track-force\"><span class=\"ml-force-label\">force</span> gravity \u00b7 the deep line is faster and costs you time itself</p>\n        <p class=\"ml-track-line\">Fall for speed and your clock runs slow while the universe's does not. Go too deep and the horizon keeps you. The one world that can end your crossing.</p>\n      </div>\n      <div class=\"ml-track-state\" data-ml-state></div>\n    </li>\n\n  </ol>\n\n  <!-- the drop: deeper into the cosmos. nothing written here. -->\n  <div class=\"ml-deep\" aria-hidden=\"true\">\n    <span class=\"ml-deep-thread\"></span>\n  </div>\n\n  <section class=\"ml-ed2\" data-ml-ed2 aria-label=\"Edition II \u2014 the voyage\">\n    <header class=\"ml-ed2-head\">\n      <p class=\"ml-edition ml-emerge\"><span class=\"ml-gold\">edition ii</span><span class=\"ml-edition-sep\">&middot;</span><span class=\"ml-gold\">the voyage</span></p>\n      <h2 class=\"ml-ed2-title ml-emerge\"><span>The voyage</span></h2>\n      <p class=\"ml-ed2-standfirst ml-short ml-emerge\">\n        Outward from home, in order of real distance. Now the machine remembers: the scars it takes,\n        the cargo it must bring home, the crew that mends it. Hand it on, and a stranger carries it further.\n      </p>\n      <p class=\"ml-ed2-standfirst ml-long ml-emerge\">\n        Outward from home, in order of real distance. Every place is real, every force on the machine\n        is physically true. And now the machine remembers: the scars it takes, the cargo it must bring\n        home whole, and a crew that mends it while you are away. Hand it on, and a stranger carries it further.\n      </p>\n      <p class=\"ml-ed2-note ml-emerge\">Four of the five have emerged, each in its place in the order of distance. The last will emerge in its own.</p>\n      <div class=\"ml-progress ml-emerge\">\n        <span class=\"ml-progress-track\"><span class=\"ml-progress-fill ml-fill-2\" data-ml-fill2></span></span>\n        <span class=\"ml-progress-read\" data-ml-read2>0 of 1 crossed</span>\n      </div>\n    </header>\n\n    <ol class=\"ml-tracks ml-tracks-2\" data-ml-ed=\"2\">\n      <!-- the voyage runs in order of distance. the gaps are worlds not yet emerged; each fills its own place. -->\n      <li class=\"ml-gap ml-emerge\" aria-hidden=\"true\"><span class=\"ml-gap-num\">01</span></li>\n      <li class=\"ml-track ml-emerge\" data-ml-index=\"6\" data-ml-key=\"mariner\"\n          data-track=\"mariner/\">\n        <span class=\"ml-track-rule\"></span>\n        <div class=\"ml-track-body\">\n          <p class=\"ml-track-num\">02</p>\n          <h2 class=\"ml-track-name\">Mariner</h2>\n          <p class=\"ml-track-place\">Valles Marineris \u00b7 Mars</p>\n          <p class=\"ml-track-force\"><span class=\"ml-force-label\">force</span> confinement \u00b7 the walls do not move</p>\n          <p class=\"ml-track-line\">A canyon four thousand kilometres long and seven deep, flown end to end from the labyrinth of the night to the plains where its water ran out. Home is light-minutes away: what it says is already old when it reaches you. Bring the panels home clear.</p>\n        </div>\n        <div class=\"ml-track-state\" data-ml-state></div>\n      </li>\n      <li class=\"ml-track ml-emerge\" data-ml-index=\"7\" data-ml-key=\"crescent\"\n          data-track=\"crescent/\">\n        <span class=\"ml-track-rule\"></span>\n        <div class=\"ml-track-body\">\n          <p class=\"ml-track-num\">03</p>\n          <h2 class=\"ml-track-name\">Crescent</h2>\n          <p class=\"ml-track-place\">Io \u00b7 the most volcanic world we know</p>\n          <p class=\"ml-track-force\"><span class=\"ml-force-label\">force</span> the squeeze, and the dose \u00b7 linger and it counts against you</p>\n          <p class=\"ml-track-line\">Low over sulphur plains, under umbrellas of gas that fall back as frost, with Jupiter filling a quarter of the sky. Through the eclipse, where the air freezes and falls, past Pele, and out through the current that joins Io to Jupiter. Bring the pictures home clear.</p>\n        </div>\n        <div class=\"ml-track-state\" data-ml-state></div>\n      </li>\n      <li class=\"ml-track ml-emerge\" data-ml-index=\"8\" data-ml-key=\"fathom\"\n          data-track=\"fathom/\">\n        <span class=\"ml-track-rule\"></span>\n        <div class=\"ml-track-body\">\n          <p class=\"ml-track-num\">04</p>\n          <h2 class=\"ml-track-name\">Fathom</h2>\n          <p class=\"ml-track-place\">Neptune \u00b7 the planet found by mathematics</p>\n          <p class=\"ml-track-force\"><span class=\"ml-force-label\">force</span> wind, then weight \u00b7 let go and the sky takes you</p>\n          <p class=\"ml-track-line\">A descent, not a crossing. Down through the fastest winds in the solar system, past the edge of a storm the size of the Earth, into a dark lit only by the machine, to where carbon is pressed into diamond and falls. Carry the sphere down sealed.</p>\n        </div>\n        <div class=\"ml-track-state\" data-ml-state></div>\n      </li>\n      <li class=\"ml-track ml-emerge\" data-ml-index=\"9\" data-ml-key=\"metronome\"\n          data-track=\"metronome/\">\n        <span class=\"ml-track-rule\"></span>\n        <div class=\"ml-track-body\">\n          <p class=\"ml-track-num\">05</p>\n          <h2 class=\"ml-track-name\">Metronome</h2>\n          <p class=\"ml-track-place\">CP 1919 \u00b7 the first pulsar ever found</p>\n          <p class=\"ml-track-force\"><span class=\"ml-force-label\">force</span> rhythm \u00b7 the beam acts on when</p>\n          <p class=\"ml-track-line\">A beam no eye has seen, turning once every 1.34 seconds. You hear it, and read it as a kick on the chart, the way it was first found. Move on the beat, bring the clock home in phase. The machine remembers what it touches.</p>\n        </div>\n        <div class=\"ml-track-state\" data-ml-state></div>\n      </li>\n    </ol>\n  </section>\n\n  <footer class=\"ml-foot\">\n    <p class=\"ml-foot-note\" data-ml-foot>\n      Each world below the first is held for when you're ready. Cross the world above it and the next opens \u2014 through Edition I, and on into Edition II. Remembered on this device alone. Nothing is sent anywhere.\n    </p>\n    <button class=\"ml-foot-reset\" type=\"button\" data-ml-reset hidden>Forget my crossings on this device</button>\n  </footer>\n\n  <!-- ============================================================\n       THE LOGBOOK \u2014 witness reports\n       Wired to Formspree: https://formspree.io/f/xvkpdkoq\n       Formspree needs no JS to work; the script here only keeps the\n       person on the page and prints a quiet acknowledgement.\n       ============================================================ -->\n  <section class=\"ml-logbook\" aria-label=\"Send word\">\n    <h2 class=\"ml-log-title\">The logbook</h2>\n    <p class=\"ml-log-note\">\n      If something behaved strangely, or a world did something it shouldn\u2019t, or you found a line\n      worth telling someone about \u2014 send word. Every report is read by a person.\n    </p>\n\n    <form class=\"ml-log-form\" action=\"https://formspree.io/f/xvkpdkoq\" method=\"POST\" data-ml-form>\n      <div class=\"ml-field\">\n        <label class=\"ml-label\" for=\"mlWhich\">Which world</label>\n        <select class=\"ml-input\" id=\"mlWhich\" name=\"world\">\n          <option>The Crossing</option>\n          <option>Ringfall</option>\n          <option>Ironlight</option>\n          <option>The Behemoth</option>\n          <option>The Well</option>\n          <option>Mariner</option>\n          <option>Crescent</option>\n          <option>Fathom</option>\n          <option>Metronome</option>\n          <option>The page itself</option>\n          <option>Something else</option>\n        </select>\n      </div>\n\n      <div class=\"ml-field\">\n        <label class=\"ml-label\" for=\"mlWord\">What happened</label>\n        <textarea class=\"ml-input ml-area\" id=\"mlWord\" name=\"message\" rows=\"5\"\n          placeholder=\"What you saw, and what you were doing when you saw it.\" required></textarea>\n      </div>\n\n      <div class=\"ml-field\">\n        <label class=\"ml-label\" for=\"mlBack\">Where to reach you <span class=\"ml-optional\">optional</span></label>\n        <input class=\"ml-input\" id=\"mlBack\" type=\"email\" name=\"email\" placeholder=\"only if you\u2019d like a reply\">\n      </div>\n\n      <!-- quiet context: helps diagnose without asking anyone to describe their machine -->\n      <input type=\"hidden\" name=\"universe\" data-ml-seed value=\"\">\n      <input type=\"hidden\" name=\"crossings\" data-ml-crossed value=\"\">\n      <input type=\"hidden\" name=\"machine\" data-ml-agent value=\"\">\n      <input type=\"text\" name=\"_gotcha\" tabindex=\"-1\" autocomplete=\"off\" aria-hidden=\"true\" class=\"ml-hp\">\n\n      <button class=\"ml-log-send\" type=\"submit\">Send word <span class=\"ml-arrow\">&rsaquo;</span></button>\n      <p class=\"ml-log-said\" data-ml-said hidden>Received. Thank you for the report.</p>\n    </form>\n  </section>\n\n</section>";
})();

(function(){
  var root = document.querySelector('.ml-descent');
  if(!root) return;

  /* ------------------------------------------------------------
     WHERE THE TRACKS LIVE — set this once.
     Must be a host that serves HTML as HTML: GitHub Pages, Netlify,
     Cloudflare Pages, or your own subdomain. NOT jsDelivr, NOT raw
     GitHub — both send .html as text/plain and the games would show
     as source code.
     ------------------------------------------------------------ */
  var TRACKS_BASE = 'https://moonline.codifiedresonance.com/';

  var STORE = 'moonline.crossings.v1';   // sovereign-local: this device only
  var tracks = Array.prototype.slice.call(root.querySelectorAll('.ml-track'));

  // ---- read what this device remembers ----
  function readCrossed(){
    try{
      var raw = window.localStorage.getItem(STORE);
      return raw ? JSON.parse(raw) : {};
    }catch(e){ return {}; }   // storage blocked (private mode / sandbox): treat as fresh, still fully playable
  }
  function writeCrossed(map){
    try{ window.localStorage.setItem(STORE, JSON.stringify(map)); }catch(e){}
  }

  var crossed = readCrossed();
  // worlds this device chose to forget: the bridge below must not bring them back
  var FORGOT = 'moonline.crossings.forgot';
  function readForgot(){ try{ var v = JSON.parse(window.localStorage.getItem(FORGOT) || '[]'); return Array.isArray(v) ? v : []; }catch(e){ return []; } }
  function writeForgot(a){ try{ window.localStorage.setItem(FORGOT, JSON.stringify(a)); }catch(e){} }
  var lineKeys = [];

  /* A track lives on its own origin now, so it cannot write to this page's
     storage and has no parent to message. It carries the crossing home in
     the link instead: ?crossed=<track>. We record it, then clean the URL so
     a refresh doesn't re-announce it. */
  (function(){
    try{
      var m = /[?&]crossed=([a-z0-9_-]+)/i.exec(window.location.search || '');
      if(!m) return;
      var key = decodeURIComponent(m[1]);
      var known = false;
      for(var i=0;i<tracks.length;i++) if(tracks[i].getAttribute('data-ml-key')===key) known = true;
      // remembered even if this page doesn't know the world yet: when it does, the crossing is already here
      crossed[key] = { at: Date.now() };
      writeCrossed(crossed);
      writeForgot(readForgot().filter(function(k){ return k !== key; }));
      if(window.history && window.history.replaceState){
        window.history.replaceState({}, '', window.location.pathname);
      }
      if(!known) return;
      // receive the witness at the veil they just lifted. but at the end of an edition there is no skipping
      // what comes next: the page opens on the drop between the editions, the gold thread coming down into the
      // voyage's beginning, and the witness descends into it themselves.
      var at = -1;
      for(var j=0;j<tracks.length;j++) if(tracks[j].getAttribute('data-ml-key')===key) at = j;
      var nxt = tracks[at+1] || tracks[at];
      var edgeOfEdition = !!(tracks[at+1] && tracks[at+1].parentNode !== tracks[at].parentNode);
      var deep = root.querySelector('.ml-deep');
      if(edgeOfEdition && deep){
        try{ if('scrollRestoration' in window.history) window.history.scrollRestoration = 'manual'; }catch(e){}
        var moved = false, mark = function(){ moved = true; };
        ['wheel','touchstart','keydown','pointerdown'].forEach(function(ev){ window.addEventListener(ev, mark, {once:true, passive:true}); });
        var land = function(){
          if(moved) return;   // once they move, the page is theirs
          try{ window.scrollTo(0, Math.max(0, deep.getBoundingClientRect().top + (window.pageYOffset||0) - 20)); }catch(e){}
        };
        land(); setTimeout(land, 60); setTimeout(land, 400); setTimeout(land, 1200);   // again as the type settles
        return;
      }
      setTimeout(function(){
        try{ nxt.scrollIntoView({behavior:'smooth', block:'center'}); }catch(e){}
      }, 650);
    }catch(e){}
  })();

  // ---- a track is OPEN if: it's the first, OR the track above it has been crossed ----
  function isOpen(i){
    if(i === 0) return true;
    var prevKey = tracks[i-1].getAttribute('data-ml-key');
    return !!crossed[prevKey];
  }

  function go(track){
    var file = track.getAttribute('data-track');
    if(!file) return;
    var base = TRACKS_BASE.replace(/\/*$/, '/');
    // hand the track this page's own address, so its return link is always right
    var from = encodeURIComponent(window.location.origin + window.location.pathname);
    window.location.href = base + file + '?from=' + from;
  }

  function paint(){
    var count = 0;
    tracks.forEach(function(track, i){
      var key = track.getAttribute('data-ml-key');
      var state = track.querySelector('[data-ml-state]');
      var done = !!crossed[key];
      var open = isOpen(i) || done;   // a world you have crossed stays open, whatever emerges above it
      if(done) count++;

      track.classList.toggle('is-open', open);
      track.classList.toggle('is-held', !open);
      track.classList.toggle('is-crossed', done);
      track.setAttribute('tabindex', open ? '0' : '-1');
      track.setAttribute('role', open ? 'link' : 'group');

      // state cell
      state.innerHTML = '';
      if(open){
        if(done){
          var tag = document.createElement('span');
          tag.className = 'ml-crossed-tag';
          tag.textContent = 'crossed · enter again';
          state.appendChild(tag);
        }else{
          var enter = document.createElement('span');
          enter.className = 'ml-enter';
          enter.innerHTML = 'Enter <span class="ml-arrow">&rsaquo;</span>';
          state.appendChild(enter);
        }
      }else{
        // HELD — a veil, not a wall. named, and openable anyway.
        var held = document.createElement('span');
        held.className = 'ml-held';
        var prevName = tracks[i-1].querySelector('.ml-track-name').textContent;
        held.innerHTML =
          '<span class="ml-held-label">held for when you\u2019re ready</span>' +
          '<span class="ml-held-open">opens when you cross ' + prevName + '</span>';
        var anyway = document.createElement('button');
        anyway.type = 'button';
        anyway.className = 'ml-held-anyway';
        anyway.textContent = 'enter anyway \u203a';
        anyway.addEventListener('click', function(ev){ ev.stopPropagation(); go(track); });
        held.appendChild(anyway);
        state.appendChild(held);
      }
    });

    // progress, edition by edition
    function edCount(ed){
      var list = tracks.filter(function(t){ return t.parentNode && t.parentNode.getAttribute('data-ml-ed') === ed; });
      var c = list.filter(function(t){ return !!crossed[t.getAttribute('data-ml-key')]; }).length;
      return {c:c, n:list.length};
    }
    var e1 = edCount('1'), e2 = edCount('2');
    var fill = root.querySelector('[data-ml-fill]');
    var read = root.querySelector('[data-ml-read]');
    if(fill) fill.style.right = (100 - (e1.c/Math.max(1,e1.n)*100)) + '%';
    if(read) read.textContent = e1.c + ' of ' + e1.n + ' crossed';
    var fill2 = root.querySelector('[data-ml-fill2]');
    var read2 = root.querySelector('[data-ml-read2]');
    if(fill2) fill2.style.right = (100 - (e2.c/Math.max(1,e2.n)*100)) + '%';
    if(read2) read2.textContent = e2.c + ' of ' + e2.n + ' crossed';

    var reset = root.querySelector('[data-ml-reset]');
    if(reset) reset.hidden = (count === 0);
  }

  // ---- entering an open/crossed world ----
  tracks.forEach(function(track, i){
    track.addEventListener('click', function(){
      if(isOpen(i)) go(track);
    });
    track.addEventListener('keydown', function(ev){
      if((ev.key === 'Enter' || ev.key === ' ') && isOpen(i)){
        ev.preventDefault(); go(track);
      }
    });
  });

  // ---- reset: forget crossings on this device ----
  var reset = root.querySelector('[data-ml-reset]');
  if(reset){
    reset.addEventListener('click', function(){
      var f = Object.keys(crossed).concat(lineKeys);
      writeForgot(f.filter(function(k, i){ return f.indexOf(k) === i; }));
      crossed = {};
      writeCrossed(crossed);
      paint();
    });
  }

  // ---- the bridge: the worlds keep their lines on their own origin. a hidden page from there tells this one
  // which worlds have a line on this device, so a crossing counts however you came home. names only.
  (function(){
    try{
      var base = TRACKS_BASE.replace(/\/*$/, '/');
      var origin = new URL(base).origin;
      window.addEventListener('message', function(ev){
        var d = ev && ev.data;
        if(ev.origin !== origin || !d || d.moonline !== 'lines' || !Array.isArray(d.keys)) return;
        lineKeys = d.keys.filter(function(k){ return /^[a-z0-9_-]+$/.test(k); });
        var forgot = readForgot(), changed = false;
        lineKeys.forEach(function(k){
          if(!crossed[k] && forgot.indexOf(k) < 0){ crossed[k] = { at: Date.now(), line: true }; changed = true; }
        });
        if(changed){ writeCrossed(crossed); paint(); }
      });
      var f = document.createElement('iframe');
      f.src = base + 'descent/bridge.html';
      f.title = 'moonline bridge'; f.setAttribute('aria-hidden', 'true'); f.tabIndex = -1;
      f.style.cssText = 'position:absolute;width:1px;height:1px;border:0;opacity:0;pointer-events:none;left:-9999px;top:0';
      root.appendChild(f);
    }catch(e){}
  })();

  // ---- API for the tracks to call on finish (via postMessage from the iframe/game) ----
  // A track, on a clean finish, can do:  parent.postMessage({moonline:'crossed', track:'crossing'}, '*')
  // and this page will remember it, opening the next veil.
  window.addEventListener('message', function(ev){
    var d = ev && ev.data;
    if(d && d.moonline === 'crossed' && d.track){
      crossed[d.track] = { at: Date.now() };
      writeCrossed(crossed);
      paint();
    }
  });

  // Also expose a direct hook if the page and game share an origin later.
  window.MOONLINE_markCrossed = function(track){
    if(!track) return;
    crossed[track] = { at: Date.now() };
    writeCrossed(crossed);
    paint();
  };

  // ---- the logbook: carry quiet context, keep the witness on the page ----
  var form = root.querySelector('[data-ml-form]');
  if(form){
    var seedField = form.querySelector('[data-ml-seed]');
    var crossField = form.querySelector('[data-ml-crossed]');
    var agentField = form.querySelector('[data-ml-agent]');
    if(agentField) agentField.value = (navigator && navigator.userAgent) || 'unknown';
    if(crossField) crossField.value = Object.keys(readCrossed()).join(', ') || 'none yet';
    if(seedField){
      // the universe a witness crossed, if any track has left one on this device
      var seen = '';
      try{
        for(var i=0;i<tracks.length;i++){
          var k = tracks[i].getAttribute('data-ml-key');
          var v = window.localStorage.getItem('moonline.line.' + k);
          if(v && v.indexOf('|') > -1) seen += (seen ? ', ' : '') + k + ':' + v.split('|')[1];
        }
      }catch(e){}
      seedField.value = seen || 'none recorded';
    }
    form.addEventListener('submit', function(ev){
      if(!form.action || form.action.indexOf('FORM_ID') > -1) return;   // not wired yet: let it post normally
      ev.preventDefault();
      var said = form.querySelector('[data-ml-said]');
      var btn = form.querySelector('.ml-log-send');
      if(btn){ btn.disabled = true; btn.textContent = 'Sending\u2026'; }
      fetch(form.action, {
        method:'POST', body:new FormData(form), headers:{'Accept':'application/json'}
      }).then(function(r){
        if(said){ said.hidden = false;
          said.textContent = r.ok ? 'Received. Thank you for the report.'
                                  : 'That didn\u2019t send. Try again, or mail us directly.'; }
        if(r.ok) form.reset();
        if(btn){ btn.disabled = false; btn.innerHTML = 'Send word <span class="ml-arrow">\u203a</span>'; }
      }).catch(function(){
        if(said){ said.hidden = false; said.textContent = 'That didn\u2019t send. Try again, or mail us directly.'; }
        if(btn){ btn.disabled = false; btn.innerHTML = 'Send word <span class="ml-arrow">\u203a</span>'; }
      });
    });
  }

  // ---- the cycle: the same fact that seeds the universe, stated back plainly ----
  // rollover is UTC Monday 00:00 — the same boundary the game's own weekly seed uses.
  function nextRollover(from){
    const d=new Date(Date.UTC(from.getUTCFullYear(),from.getUTCMonth(),from.getUTCDate()));
    const day=d.getUTCDay();               // 0=Sun..6=Sat, Mon=1
    let add=(8-day)%7; if(add===0)add=7;   // always the *next* Monday, never "today"
    d.setUTCDate(d.getUTCDate()+add);
    return d;
  }
  function paintCycle(){
    const el=root.querySelector('[data-ml-cycle]');
    if(!el) return;
    const now=new Date();
    const ms=Math.max(0,nextRollover(now)-now);
    const totalMin=Math.floor(ms/60000);
    const d=Math.floor(totalMin/1440);
    const h=Math.floor((totalMin%1440)/60);
    const dWord=d===1?'day':'days';
    const hPart=h>0?(', '+h+(h===1?' hour':' hours')):'';
    el.textContent='This universe holds for '+d+' '+dWord+hPart+'.';
  }
  paintCycle();
  setInterval(paintCycle,60000);   // quiet — no seconds, no flashing, just true

  paint();


  // ---- a phone has no hover: each world plays once, softly, as it comes into view ----
  (function(){
    var touch = window.matchMedia && window.matchMedia('(hover: none)').matches;
    var still = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if(!touch || still || !('IntersectionObserver' in window)) return;
    var LAST = {crossing:6200, ringfall:3200, ironlight:5400, behemoth:8600, mariner:9400, crescent:6000, fathom:7000, metronome:4200};
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(en){
        if(!en.isIntersecting) return;
        var t = en.target, k = t.getAttribute('data-ml-key');
        io.unobserve(t);
        setTimeout(function(){
          t.classList.add('ml-felt');
          setTimeout(function(){ t.classList.remove('ml-felt'); }, LAST[k] || 6000);
        }, 900);   // let the world settle into view first
      });
    }, {threshold:0.6});
    tracks.forEach(function(t){
      var k = t.getAttribute('data-ml-key');
      if(LAST[k]) io.observe(t);   // the well is not played here
    });
  })();

  // ---- deeper: the cosmos comes up behind the page as Edition II nears ----
  (function(){
    var cosmos = root.querySelector('[data-ml-cosmos]');
    var deep = root.querySelector('.ml-deep');
    if(!cosmos || !deep) return;
    // a sky that was not there before: a few hundred points, the same every time
    try{
      var st = document.createElement('div'); st.className = 'ml-stars';
      var a = 7, sh = [];
      function rnd(){ a = (a * 16807) % 2147483647; return a / 2147483647; }
      for(var i=0;i<260;i++){
        var x = (rnd()*100).toFixed(2), y = (rnd()*100).toFixed(2), b = rnd(), warm = rnd() < 0.12;
        var al = (0.18 + b*b*0.7).toFixed(2);
        sh.push(x + 'vw ' + y + 'vh 0 ' + (b > 0.93 ? '0.5px ' : '0 ') + (warm ? 'rgba(255,232,196,' : 'rgba(214,226,255,') + al + ')');
      }
      st.style.boxShadow = sh.join(',');
      cosmos.appendChild(st);
    }catch(e){}
    var raf = 0;
    function depth(){
      raf = 0;
      var vh = window.innerHeight || 800;
      var r = deep.getBoundingClientRect();
      var k = (vh - r.top) / (r.height + vh * 0.6);
      // and it ends as gently as it began, at the note that holds every world
      var foot = root.querySelector('.ml-foot');
      if(foot){ var f = foot.getBoundingClientRect(); k = Math.min(k, (f.top - vh * 0.3) / (vh * 0.55)); }
      cosmos.style.opacity = String(Math.max(0, Math.min(1, k)));
    }
    function ask(){ if(!raf) raf = window.requestAnimationFrame(depth); }
    window.addEventListener('scroll', ask, {passive:true});
    window.addEventListener('resize', ask);
    depth();
  })();

  // ---- emerging: out of the dark, once, as each thing comes into view ----
  (function(){
    var els = Array.prototype.slice.call(root.querySelectorAll('.ml-emerge'));
    if(!('IntersectionObserver' in window)){ els.forEach(function(e){ e.classList.add('is-in'); }); return; }
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(en){
        if(en.isIntersecting){ en.target.classList.add('is-in'); io.unobserve(en.target); }
      });
    }, {rootMargin:'0px 0px -8% 0px', threshold:0.12});
    els.forEach(function(e){ io.observe(e); });
  })();
})();
